import json
import re

def remove_comments_from_line(line):
    if line.strip().startswith('#'):
        return None

    in_string = False
    string_char = None
    result = []
    i = 0

    while i < len(line):
        char = line[i]

        if char in ['"', "'"] and (i == 0 or line[i-1] != '\\'):
            if not in_string:
                in_string = True
                string_char = char
            elif char == string_char:
                in_string = False

        if char == '#' and not in_string:
            result_str = ''.join(result).rstrip()
            if result_str:
                return result_str + '\n'
            return None

        result.append(char)
        i += 1

    return ''.join(result)

with open('main.ipynb', 'r', encoding='utf-8') as f:
    notebook = json.load(f)

for cell in notebook['cells']:
    if cell['cell_type'] == 'code':
        new_source = []
        for line in cell['source']:
            cleaned_line = remove_comments_from_line(line)
            if cleaned_line is not None:
                new_source.append(cleaned_line)
            elif not line.strip():
                new_source.append(line)
        cell['source'] = new_source

with open('main.ipynb', 'w', encoding='utf-8') as f:
    json.dump(notebook, f, ensure_ascii=False, indent=1)

print('✅ Comentários removidos com sucesso!')
print(f'Total de células processadas: {len(notebook["cells"])}')
